export function zip(files){const chunks=[],central=[];let offset=0;for(const [name,raw] of Object.entries(files)){const path=utf.encode(name),body=typeof raw==='string'?utf.encode(raw):raw,crc=crc32(body),head=join([u32(0x04034b50),u16(20),u16(0x800),u16(0),u16(0),u16(0),u32(crc),u32(body.length),u32(body.length),u16(path.length),u16(0),path]);chunks.push(head,body);central.push(join([u32(0x02014b50),u16(20),u16(20),u16(0x800),u16(0),u16(0),u16(0),u32(crc),u32(body.length),u32(body.length),u16(path.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),path]));offset+=head.length+body.length;}const dir=join(central);return join([...chunks,dir,u32(0x06054b50),u16(0),u16(0),u16(central.length),u16(central.length),u32(dir.length),u32(offset),u16(0)]);}
export async function unzip(bytes){const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('Neplatný soubor Excel.');const count=v.getUint16(end+10,true);if(count>200)throw Error('Sešit má příliš mnoho částí.');let at=v.getUint32(end+16,true),total=0;const files={};for(let i=0;i<count;i++){if(v.getUint32(at,true)!==0x02014b50)throw Error('Poškozený sešit.');const method=v.getUint16(at+10,true),crc=v.getUint32(at+16,true),compressed=v.getUint32(at+20,true),size=v.getUint32(at+24,true),len=v.getUint16(at+28,true),extra=v.getUint16(at+30,true),comment=v.getUint16(at+32,true),pos=v.getUint32(at+42,true),name=decode.decode(bytes.slice(at+46,at+46+len));total+=size;if(total>20000000)throw Error('Rozbalený sešit je příliš velký.');const start=pos+30+v.getUint16(pos+26,true)+v.getUint16(pos+28,true);let body=bytes.slice(start,start+compressed);if(method===8){const reader=new Blob([body]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader(),parts=[];let expanded=0;while(true){const {done,value}=await reader.read();if(done)break;expanded+=value.length;if(expanded>size||expanded>20000000){await reader.cancel();throw Error('Sešit překračuje povolenou velikost.');}parts.push(value);}body=join(parts);}else if(method!==0)throw Error('Nepodporované komprimování sešitu.');if(body.length!==size||crc32(body)!==crc)throw Error('Kontrola souboru selhala.');files[name]=decode.decode(body);at+=46+len+extra+comment;}return files;}
const xml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function sheet(rows){return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="3" topLeftCell="A4" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="24" customWidth="1"/><col min="2" max="2" width="53" customWidth="1"/><col min="3" max="8" width="22" customWidth="1"/></cols><sheetData>${rows.map((row,i)=>`<row r="${i+1}">${row.map((val,j)=>{const a=String.fromCharCode(65+j)+(i+1),style=i===0||i===2?' s="1"':'';return typeof val==='number'?`<c r="${a}"${style}><v>${Number.isFinite(val)?val:0}</v></c>`:`<c r="${a}" t="inlineStr"${style}><is><t xml:space="preserve">${xml(val)}</t></is></c>`;}).join('')}</row>`).join('')}</sheetData></worksheet>`;}
export function excelBytes(r){const labels={own:['Vlastní měsíční vklad','Kč / měsíc'],employer:['Příspěvek firmy','Kč / měsíc'],otherOwn:['Odpočty na jiné produkty','Kč / rok'],otherEmployer:['Jiné příspěvky firmy','Kč / rok'],salary:['Hrubá mzda','Kč / měsíc'],employees:['Počet zaměstnanců','osob'],age:['Věk','let'],years:['Doba investování','let'],initial:['Počáteční investice','Kč'],rate:['Modelový roční výnos','% ročně'],inflation:['Inflace','% ročně'],mode:['Srovnání: gross / budget','režim']},plan=[['MUJ-DIP',1,'Jiří Janoušek'],['Upravujte sloupec C. Potom sešit importujte zpět do aplikace.'],['Klíč','Nastavení','Hodnota','Jednotka'],...Object.entries(r.s).map(([k,v])=>[k,labels[k]?.[0]||k,v,labels[k]?.[1]||''])],growth=[['MŮJ-DIP · Vývoj investice'],['Orientační hodnoty; daňová úspora je mimo DIP. Roční poplatek se neodečítá.'],['Rok','Věk','Vaše vklady Kč','Firma Kč','Hodnota DIP Kč','Zhodnocení Kč','Úspora daně Kč','Dnešní ceny Kč'],...r.points.map(p=>[p.year,r.s.age+p.year,p.own,p.employer,p.value,p.gain,p.tax,p.real])],summary=[['MŮJ-DIP · Přehled'],['Orientační model s parametry roku 2026. Výnos není garantovaný.'],['Položka','Jednotka','Hodnota'],['Hodnota DIP','Kč',r.end.value],['Roční úspora daně','Kč',r.personalTax],['Náklad firmy na DIP — tým / rok','Kč',r.dipCost*r.s.employees],['Úspora firmy — tým / rok','Kč',r.companySaving*r.s.employees],['Hodnota navíc pro zaměstnance / rok','Kč',r.employeeDifference]];
summary.push(['Upozornění','Upozornění: Jde o orientační model bez záruky správnosti či dosažení uvedených výsledků, nikoli o investiční, daňové nebo právní doporučení ani nabídku konkrétního produktu. Výnos ani návratnost vložených prostředků nejsou garantované. Hodnota investice může kolísat a můžete utrpět ztrátu. Daňová podpora závisí na splnění zákonných podmínek a individuální situaci; pravidla se mohou měnit. Před rozhodnutím ověřte aktuální podmínky, rizika a náklady konkrétní investice.']);const names=['Plan','Vyvoj','Prehled'],files={'[Content_Types].xml':`<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${names.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`,'_rels/.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':`<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${names.map((n,i)=>`<sheet name="${n}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`,'xl/_rels/workbook.xml.rels':`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${names.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`,'xl/styles.xml':'<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FF292013"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFE4C780"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf fontId="0" fillId="0" borderId="0" xfId="0"/><xf fontId="1" fillId="2" borderId="0" xfId="0" applyFill="1" applyFont="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'};[plan,growth,summary].forEach((rows,i)=>files[`xl/worksheets/sheet${i+1}.xml`]=sheet(rows));return zip(files);}
export async function readExcel(bytes){const files=await unzip(bytes),parser=new DOMParser(),shared=[];if(files['xl/sharedStrings.xml'])for(const si of parser.parseFromString(files['xl/sharedStrings.xml'],'application/xml').getElementsByTagName('si'))shared.push(si.textContent);const doc=parser.parseFromString(files['xl/worksheets/sheet1.xml']||'','application/xml');if(doc.getElementsByTagName('parsererror').length)throw Error('Sešit nelze přečíst.');const values={};for(const c of doc.getElementsByTagName('c')){const v=c.getElementsByTagName('v')[0]?.textContent;values[c.getAttribute('r')]=c.getAttribute('t')==='s'?shared[Number(v)]:c.getAttribute('t')==='inlineStr'?c.getElementsByTagName('is')[0]?.textContent:v;}if(values.A1!=='MUJ-DIP')throw Error('Importujte sešit exportovaný z MŮJ-DIP.');const settings={};for(const row of doc.getElementsByTagName('row')){const n=Number(row.getAttribute('r')),key=values['A'+n];if(Object.hasOwn(DEFAULTS,key)){const value=values['C'+n];settings[key]=key==='mode'?value:value===undefined||value===''?null:Number(String(value).replace(',','.'));}}return validate({app:'MUJ-DIP',version:1,settings});}
export function pdfWithPlan(bytes,s){return join([bytes,utf.encode('\n%MUJ-DIP:'+encodePlan(s)+'\n')]);}
function be(n){return new Uint8Array([n>>>24&255,n>>>16&255,n>>>8&255,n&255]);}
export function pngWithPlan(bytes,s){const type=utf.encode('tEXt'),data=utf.encode('MUJ-DIP\0'+encodePlan(s)),chunk=join([be(data.length),type,data,be(crc32(join([type,data])))]);return join([bytes.slice(0,-12),chunk,bytes.slice(-12)]);}
export async function importPlan(file){if(file.size>20000000)throw Error('Soubor je příliš velký (maximum 20 MB).');const bytes=new Uint8Array(await file.arrayBuffer()),name=file.name.toLowerCase();if(name.endsWith('.xlsx'))return readExcel(bytes);if(name.endsWith('.pdf')){const match=decode.decode(bytes.slice(-50000)).match(/%MUJ-DIP:([A-Za-z0-9+/=]+)/);if(!match)throw Error('Toto PDF nemá uložený plán. Importujte PDF exportované z MŮJ-DIP.');return decodePlan(match[1]);}if(name.endsWith('.png')){if(bytes.length<20||bytes[0]!==137||decode.decode(bytes.slice(1,4))!=='PNG')throw Error('Neplatný obrázek PNG.');const v=new DataView(bytes.buffer);let pos=8;while(pos+12<=bytes.length){const size=v.getUint32(pos);if(pos+12+size>bytes.length)throw Error('Poškozený PNG.');if(decode.decode(bytes.slice(pos+4,pos+8))==='tEXt'){const text=decode.decode(bytes.slice(pos+8,pos+8+size));if(text.startsWith('MUJ-DIP\0')){if(crc32(bytes.slice(pos+4,pos+8+size))!==v.getUint32(pos+8+size))throw Error('Poškozená data plánu.');return decodePlan(text.slice(8));}}pos+=12+size;}throw Error('Obrázek neobsahuje plán. Použijte původní PNG export z MŮJ-DIP, nikoli snímek obrazovky.');}if(name.endsWith('.json'))return validate(JSON.parse(decode.decode(bytes)));throw Error('Vyberte Excel XLSX, PDF, PNG nebo JSON z MŮJ-DIP.');}
export function saveFile(name,bytes,type){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
